package org.xingmu.tv;
import java.util.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import org.json.*;import javax.xml.parsers.*;import org.w3c.dom.*;import org.xml.sax.InputSource;
/** Standard MacCMS JSON/XML response parser, no VIP resolver or script execution. */
public final class VodApi {
 public static final class Movie{public final String id,title,category,year,play,poster,area,actor,summary,tags;Movie(String i,String t,String c,String y,String p){this(i,t,c,y,p,"","","","");}Movie(String i,String t,String c,String y,String p,String pic,String region,String cast,String description){this(i,t,c,y,p,pic,region,cast,description,"");}Movie(String i,String t,String c,String y,String p,String pic,String region,String cast,String description,String genre){tags=genre;id=i;title=t;category=c;year=y;play=p;poster=pic;area=region;actor=cast;summary=description;}}
 public static String query(String api,String key,String value)throws IOException{try{URI uri=new URI(api.trim());List<String> fields=new ArrayList<>();String query=uri.getRawQuery();if(query!=null)for(String part:query.split("&")){String name=URLDecoder.decode(part.split("=",2)[0],"UTF-8");if(!Arrays.asList("ac","wd","ids","pg","t").contains(name))fields.add(part);}fields.add("ac=detail");fields.add(key+"="+URLEncoder.encode(value,"UTF-8"));StringBuilder joined=new StringBuilder();for(String field:fields){if(joined.length()>0)joined.append("&");joined.append(field);}return api.trim().split("[?#]",2)[0]+"?"+joined;}catch(Exception e){throw new IOException("影视 API 地址无效",e);}}
 public static List<Movie> browse(String api,String category)throws IOException{return browse(api,category,1);}
 public static List<Movie> browse(String api,String category,int page)throws IOException{if("全部".equals(category))return parse(PublicHttp.get(query(api,"pg",String.valueOf(page))));String text=PublicHttp.get(query(api,"pg","1").replace("ac=detail","ac=list"));List<String> ids=categoryIds(text,category);if(ids.isEmpty())return Collections.emptyList();List<Movie> result=new ArrayList<>();for(String id:ids){result.addAll(parse(PublicHttp.get(query(api,"t",id)+"&pg="+page)));if(result.size()>=60)break;}return result;}
 public static List<String> categoryIds(String text,String selected)throws IOException{List<String> ids=new ArrayList<>();try{JSONObject root=new JSONObject(text);JSONArray types=root.optJSONArray("class");if(types==null)throw new IOException("该源未提供标准分类目录");for(int n=0;n<types.length();n++){JSONObject type=types.getJSONObject(n);if(FilmCategory.matches(type.optString("type_name"),selected)){String id=type.optString("type_id");if(!id.isEmpty()&&!ids.contains(id))ids.add(id);if(ids.size()>=3)break;}}return ids;}catch(JSONException e){throw new IOException("该源未提供标准 JSON 分类目录",e);}}
 public static List<Movie> browseGenre(String api,String genre,int page)throws IOException{List<String> ids=new ArrayList<>();try{JSONArray classes=new JSONObject(PublicHttp.get(query(api,"pg","1").replace("ac=detail","ac=list"))).optJSONArray("class");if(classes!=null)for(int n=0;n<classes.length();n++){JSONObject type=classes.getJSONObject(n);String id=type.optString("type_id");if(!id.isEmpty()&&GenreSearch.matches(type.optString("type_name"),genre)&&!ids.contains(id))ids.add(id);if(ids.size()>=3)break;}}catch(JSONException e){/* XML sources can still provide genre metadata on the detail page. */}List<Movie> out=new ArrayList<>();if(ids.isEmpty()){for(Movie movie:parse(PublicHttp.get(query(api,"pg",String.valueOf(page)))))if(GenreSearch.matches(movie.category+" "+movie.tags,genre))out.add(movie);}else for(String id:ids)out.addAll(parse(PublicHttp.get(query(api,"t",id)+"&pg="+page)));return out;}
 public static List<Movie> parse(String response)throws IOException{if(response.length()>1_000_000)throw new IOException("影视响应过大");List<Movie> out=new ArrayList<>();try{if(response.trim().startsWith("<")){DocumentBuilderFactory factory=DocumentBuilderFactory.newInstance();factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);factory.setFeature("http://xml.org/sax/features/external-general-entities",false);factory.setFeature("http://xml.org/sax/features/external-parameter-entities",false);Document doc=factory.newDocumentBuilder().parse(new InputSource(new StringReader(response)));if(!doc.getDocumentElement().getTagName().equals("rss"))throw new IOException("接口未返回标准影视 XML");NodeList videos=doc.getElementsByTagName("video");for(int n=0;n<Math.min(videos.getLength(),30);n++){Element v=(Element)videos.item(n);StringBuilder playlist=new StringBuilder();NodeList dd=v.getElementsByTagName("dd");for(int j=0;j<dd.getLength();j++){if(playlist.length()>0)playlist.append("$$$");playlist.append(dd.item(j).getTextContent());}out.add(new Movie(value(v,"id"),value(v,"name"),value(v,"type"),value(v,"year"),playlist.toString(),value(v,"pic"),value(v,"area"),value(v,"actor"),value(v,"des"),value(v,"class")));}}
 else{JSONObject root=new JSONObject(response);JSONArray list=root.optJSONArray("list");if(list==null)throw new IOException("接口未返回标准影视列表");for(int n=0;n<Math.min(list.length(),30);n++){JSONObject v=list.getJSONObject(n);out.add(new Movie(v.optString("vod_id"),v.optString("vod_name","未命名"),v.optString("type_name","其他"),v.optString("vod_year"),v.optString("vod_play_url"),v.optString("vod_pic"),v.optString("vod_area"),v.optString("vod_actor"),v.optString("vod_content"),v.optString("vod_class")));}}return out;}catch(IOException e){throw e;}catch(Exception e){throw new IOException("影视接口响应格式不支持",e);}}
 private static String value(Element parent,String name){NodeList nodes=parent.getElementsByTagName(name);return nodes.getLength()==0?"":nodes.item(0).getTextContent();}
 public static String episodes(Movie movie,String siteKey,String source)throws IOException{try{LinkedHashMap<String,JSONObject> items=new LinkedHashMap<>();for(String group:movie.play.split("\\$\\$\\$")){int number=0;for(String part:group.split("#")){number++;String[] row=part.split("\\$",2);String title=row.length==2?row[0]:"第 "+number+" 项",url=row[row.length-1].trim();if(!CatalogParser.safeMediaUrl(url))continue;JSONObject item=items.get(title);if(item==null){if(items.size()>=300)throw new IOException("单部影视最多支持 300 项");String key=siteKey+"\n"+movie.id+"\n"+title;byte[] hash=java.security.MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));StringBuilder id=new StringBuilder("vod_");for(int k=0;k<12;k++)id.append(String.format(Locale.ROOT,"%02x",hash[k]&255));item=new JSONObject().put("id",id.toString()).put("title",movie.title+" · "+title).put("section","films").put("category",movie.category.isEmpty()?"其他":movie.category).put("country","未分类").put("url",url).put("mode","stream").put("source",source).put("license","用户导入的影视 API 提供媒体");items.put(title,item);}else if(!item.getString("url").equals(url)){JSONArray backups=item.optJSONArray("backupUrls");if(backups==null){backups=new JSONArray();item.put("backupUrls",backups);}boolean duplicate=false;for(int k=0;k<backups.length();k++)if(backups.getString(k).equals(url))duplicate=true;if(!duplicate&&backups.length()<7)backups.put(url);}}}if(items.isEmpty())throw new IOException("该内容没有直接播放地址，可能依赖解析插件");JSONArray list=new JSONArray();for(JSONObject item:items.values())list.put(item);return new JSONObject().put("authorized",true).put("items",list).toString();}catch(IOException e){throw e;}catch(Exception e){throw new IOException("影视播放列表格式错误",e);}}
}
